    /// <summary>
    /// Этап обработки заказа (статус `PROCESSING`) или причина отмены заказа (статус `CANCELLED`).
    /// <br/>
    /// <br/>* Значения для заказа в статусе `PROCESSING`:
    /// <br/>
    /// <br/>    * `STARTED` — заказ подтвержден, его можно начать обрабатывать.
    /// <br/>
    /// <br/>    * `READY_TO_SHIP` — заказ собран и готов к отправке.
    /// <br/>
    /// <br/>* Значения для заказа в статусе `CANCELLED`:
    /// <br/>
    /// <br/>    * `RESERVATION_EXPIRED` — покупатель не завершил оформление зарезервированного заказа в течение 10 минут.
    /// <br/>
    /// <br/>    * `USER_NOT_PAID` — покупатель не оплатил заказ (для типа оплаты `PREPAID`) в течение 30 минут.
    /// <br/>
    /// <br/>    * `USER_UNREACHABLE` — не удалось связаться с покупателем. Для отмены с этой причиной необходимо выполнить условия:
    /// <br/>
    /// <br/>      * не менее 3 звонков с 8 до 21 в часовом поясе покупателя;
    /// <br/>      * перерыв между первым и третьим звонком не менее 90 минут;
    /// <br/>      * соединение не короче 5 секунд.
    /// <br/>
    /// <br/>      Если хотя бы одно из этих условий не выполнено (кроме случая, когда номер недоступен), отменить заказ не получится. Вернется ответ с кодом ошибки 400.
    /// <br/>
    /// <br/>    * `USER_CHANGED_MIND` — покупатель отменил заказ по личным причинам.
    /// <br/>
    /// <br/>    * `USER_REFUSED_DELIVERY` — покупателя не устроили условия доставки.
    /// <br/>
    /// <br/>    * `USER_REFUSED_PRODUCT` — покупателю не подошел товар.
    /// <br/>
    /// <br/>    * `SHOP_FAILED` — магазин не может выполнить заказ.
    /// <br/>
    /// <br/>    * `USER_REFUSED_QUALITY` — покупателя не устроило качество товара.
    /// <br/>
    /// <br/>    * `USER_IDENTIFICATION_MISMATCH` — идентификационный документ покупателя не совпадает с данными в заказе.
    /// <br/>
    /// <br/>    * `PURCHASE_GROUP_THRESHOLD_NOT_REACHED_CANCELLED` — заказ участвовал в групповой покупке и был отменен, потому что не было достигнуто нужное количество покупок.
    /// <br/>
    /// <br/>    * `REPLACING_ORDER` — покупатель решил заменить товар другим по собственной инициативе.
    /// <br/>
    /// <br/>    * `PROCESSING_EXPIRED` — значение более не используется.
    /// <br/>
    /// <br/>    * `PICKUP_EXPIRED` — закончился срок хранения заказа в пункт выдачи.
