    /// <summary>
    /// Статус возврата денег:
    /// <br/>
    /// <br/>* `STARTED_BY_USER` — создан покупателем из личного кабинета.
    /// <br/>
    /// <br/>* `REFUND_IN_PROGRESS` — ждет решение о возврате денег (на рассмотрении).
    /// <br/>
    /// <br/>* `REFUNDED` — деньги возвращены.
    /// <br/>
    /// <br/>* `FAILED` — невозможно провести возврат покупателю.
    /// <br/>
    /// <br/>* `WAITING_FOR_DECISION` — ожидает решения (DBS).
    /// <br/>
    /// <br/>* `DECISION_MADE` — по возврату принято решение (DBS).
    /// <br/>
    /// <br/>* `REFUNDED_WITH_BONUSES` — возврат осуществлен баллами Плюса или промокодом.
    /// <br/>
    /// <br/>* `REFUNDED_BY_SHOP` — магазин сделал самостоятельно возврат денег.
    /// <br/>
    /// <br/>* `COMPLETE_WITHOUT_REFUND` — возврат денег не требуется.
    /// <br/>
    /// <br/>* `CANCELLED` — возврат отменен.
    /// <br/>
    /// <br/>* `REJECTED` — возврат отклонен модерацией или в ПВЗ.
    /// <br/>
    /// <br/>* `PREMODERATION_DISPUTE` — по возврату открыт спор (FBY, FBS и Экспресс).
    /// <br/>
    /// <br/>* `PREMODERATION_DECISION_WAITING` — ожидает решения (FBY, FBS и Экспресс).
    /// <br/>
    /// <br/>* `PREMODERATION_DECISION_MADE` — по возврату принято решение (FBY, FBS и Экспресс).
    /// <br/>
